  `paused_at` char(24) COLLATE utf8mb4_bin NOT NULL,
  PRIMARY KEY (`worker_id`),
  UNIQUE KEY `seq` (`seq`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `worker_processes` (
  `process_id` varchar(255) COLLATE utf8mb4_bin NOT NULL,
  `pid` int NOT NULL,
  `host` varchar(255) COLLATE utf8mb4_bin NOT NULL,
  `slots` int NOT NULL,
  `max_slots` int NOT NULL,
  `busy` int NOT NULL,
  `index_base` int NOT NULL,
  `started_at` char(24) COLLATE utf8mb4_bin NOT NULL,
  `reported_at` char(24) COLLATE utf8mb4_bin NOT NULL,
  PRIMARY KEY (`process_id`),
  KEY `worker_processes_reported` (`reported_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `worker_run_attempts` (
  `run_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `attempt` int NOT NULL,
  `lease_token` bigint NOT NULL,
  `worker_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `started_at` char(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `finished_at` char(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `failure_class` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `tokens` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`run_id`,`attempt`),
  CONSTRAINT `worker_run_attempts_ibfk_1` FOREIGN KEY (`run_id`) REFERENCES `worker_runs` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `worker_run_steps` (
  `run_id` varchar(64) COLLATE utf8mb4_bin NOT NULL,
  `step_id` varchar(64) COLLATE utf8mb4_bin NOT NULL,
  `attempt` int NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_bin NOT NULL,
  `result_ref` mediumtext COLLATE utf8mb4_bin,
  `error_code` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL,
  `started_at` char(24) COLLATE utf8mb4_bin NOT NULL,
  `finished_at` char(24) COLLATE utf8mb4_bin DEFAULT NULL,
  PRIMARY KEY (`run_id`,`step_id`),
  CONSTRAINT `worker_run_steps_run` FOREIGN KEY (`run_id`) REFERENCES `worker_runs` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `worker_runs` (
  `seq` bigint NOT NULL AUTO_INCREMENT,
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `work_item_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `kind` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `idempotency_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `attempt` int NOT NULL,
  `lease_owner` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `lease_token` bigint NOT NULL,
  `lease_expires_at` char(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `outcome` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `acknowledged_at` char(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `created_at` char(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `updated_at` char(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `started_at` char(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `finished_at` char(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `not_before` char(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `input` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `paused_at` char(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `paused_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `pause_state` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `actor_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `transcript_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `session_tokens` bigint DEFAULT NULL,
  `code_version` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL,
  `deadline_at` char(24) COLLATE utf8mb4_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `seq` (`seq`),
  UNIQUE KEY `idempotency_key` (`idempotency_key`),
  KEY `runs_claim` (`status`,`kind`,`created_at`,`seq`),
  KEY `runs_work_item` (`work_item_id`),
  KEY `runs_finished` (`finished_at`),
  KEY `worker_runs_lease` (`status`,`lease_expires_at`),
  CONSTRAINT `worker_runs_ibfk_1` FOREIGN KEY (`work_item_id`) REFERENCES `controller_work_items` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
